"use client"

import Link from "next/link"
import { useMemo, useState } from "react"
import { useDemoStorageState } from "@/lib/use-demo-storage-state"
import { Activity, ArrowDownToLine, ArrowRight, BadgeCheck, Bell, BriefcaseBusiness, Building2, CalendarDays, ChevronDown, CircleDollarSign, ClipboardList, CreditCard, FileCheck2, Filter, Heart, LayoutDashboard, LifeBuoy, LogOut, Menu, MessageCircle, MoreHorizontal, Plus, Search, ShieldAlert, ShieldCheck, Settings, Star, Users, Wallet, X, UserRound, Hammer, Megaphone, LockKeyhole, type LucideIcon } from "lucide-react"
import type { ApplicationRecord, DemoBooking, Job, Locale } from "@/lib/carava-data"
import { businessProfiles, dashboardRecords, dashboardSections, demoAuditRecords, demoUsers, disputeRecords, formatDate, formatETB, initialVerificationStatuses, workers } from "@/lib/carava-data"
import { publishDemoNotification, sendDemoInboxMessage, useDemoInbox, useDemoNotifications, type DemoRole } from "@/lib/carava-demo-activity"
import { localeLabels, t, translateText } from "@/lib/carava-i18n"
