const roleNames: Record<string, string> = { account: "Customer space", worker: "Worker workspace", business: "Business workspace", admin: "Platform operations" }
const displayNames: Record<string, string> = { account: "Mekdes Alemu", worker: "Abebe Tadesse", business: "Kora Coffee House", admin: "Carava Admin" }
const roleInitials: Record<string, string> = { account: "MA", worker: "AT", business: "KC", admin: "CA" }
const icons = [LayoutDashboard, UserRound, Users, ClipboardList, CalendarDays, BriefcaseBusiness, FileCheck2, MessageCircle, Bell, CreditCard, FileCheck2, Star, ShieldAlert, Settings, LockKeyhole, Hammer, Wallet, Building2, Activity, Filter, Megaphone, LifeBuoy, CircleDollarSign]

function sectionHref(role: string, section: string) {
  return section === "Overview" ? `/${role}` : `/${role}/${section.toLowerCase().replaceAll("&", "and").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "")}`
}
function titleFromPath(role: string, pathname: string) {
  const part = pathname.replace(`/${role}`, "").replace(/^\//, "").split("/")[0]
  if (!part) return "Overview"
  return dashboardSections[role].find((section) => section.toLowerCase().replaceAll("&", "and").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") === part) ?? part.split("-").map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join(" ")
}

export function DashboardPage({ role, pathname, locale, onLocaleChange, savedIds, bookings, jobs: marketplaceJobs, applications, displayName, onToggleSave, onUpdateBooking, onApplyJob, onCreateJob, onUpdateJob, onUpdateJobStatus, onUpdateApplication, onToast }: { role: "account" | "worker" | "business" | "admin"; pathname: string; locale: Locale; onLocaleChange: (locale: Locale) => void; savedIds: string[]; bookings: DemoBooking[]; jobs: Job[]; applications: ApplicationRecord[]; displayName?: string; onToggleSave: (id: string) => void; onUpdateBooking: (id: string, status: DemoBooking["status"], update?: Partial<Pick<DemoBooking, "date" | "schedule" | "details" | "completionEvidence">>) => void; onApplyJob: (job: Job) => void; onCreateJob: (title: string, description: string, category?: string, owner?: "business" | "customer") => void; onUpdateJob: (id: string, title: string, description: string, category?: string) => void; onUpdateJobStatus: (id: string, status: NonNullable<Job["moderationStatus"]>) => void; onUpdateApplication: (id: string, stage: ApplicationRecord["stage"]) => void; onToast: (message: string) => void }) {
  const [menuOpen, setMenuOpen] = useState(false)
  const [verificationStatuses] = useDemoStorageState("carava-demo-verification-statuses", initialVerificationStatuses)
  const activeSection = titleFromPath(role, pathname)
  const roleLabel = translateText(locale, roleNames[role])
  const pendingVerificationCount = dashboardRecords("admin", "Worker verification").filter((row) => /pending/i.test(verificationStatuses[row.ID] ?? row.Status ?? "")).length
  return <main className="dashboard-shell"><aside aria-label={`${roleLabel} navigation`} className={`dashboard-sidebar ${menuOpen ? "is-open" : ""}`}><div className="dashboard-brand"><Brand compact /><button aria-label={translateText(locale, "Close dashboard menu")} className="icon-button dashboard-close-menu" onClick={() => setMenuOpen(false)} type="button"><X size={17} /></button></div><div className="sidebar-label">{roleLabel}</div><nav aria-label={translateText(locale, "Dashboard sections")} className="sidebar-links">{dashboardSections[role].map((section, index) => { const Icon = icons[index % icons.length]; const href = sectionHref(role, section); return <Link aria-current={activeSection === section ? "page" : undefined} className={`sidebar-link ${activeSection === section ? "active" : ""}`} href={href} key={section} onClick={() => setMenuOpen(false)}><Icon size={15} /><span>{translateText(locale, section)}</span>{role === "admin" && section === "Worker verification" && pendingVerificationCount > 0 && <span className="sidebar-count">{pendingVerificationCount}</span>}</Link> })}</nav><div className="sidebar-footer"><Link className="sidebar-link" href="/"><LogOut size={15} /><span>{translateText(locale, "Back to marketplace")}</span></Link><div className="role-switcher"><span>{translateText(locale, "Demo workspaces · UI only")}</span>{(["account", "worker", "business", "admin"] as const).filter((item) => item !== role).map((item) => <Link href={`/${item}`} key={item}>{translateText(locale, roleNames[item])}</Link>)}</div><div className="demo-profile"><span className="demo-profile-avatar">{roleInitials[role]}</span><span><strong>{displayName ?? displayNames[role]}</strong><small>{translateText(locale, "Demo account")} · {roleLabel}</small></span><MoreHorizontal size={17} /></div></div></aside>{menuOpen && <button aria-label={translateText(locale, "Close navigation")} className="dashboard-sidebar-backdrop" onClick={() => setMenuOpen(false)} type="button" />}
    <section className="dashboard-main"><header className="dashboard-topbar"><div className="dashboard-topbar-left"><button aria-expanded={menuOpen} aria-label={translateText(locale, "Open dashboard menu")} className="section-mobile-menu icon-button" onClick={() => setMenuOpen(true)} type="button"><Menu size={18} /></button><div className="dashboard-breadcrumb">{roleLabel} <span> / </span><strong>{translateText(locale, activeSection)}</strong></div></div><div className="dashboard-tools"><label className="locale-picker"><span className="sr-only">{translateText(locale, "Choose language")}</span><select aria-label={translateText(locale, "Choose language")} onChange={(event) => onLocaleChange(event.target.value as Locale)} value={locale}>{Object.entries(localeLabels).map(([code, label]) => <option key={code} value={code}>{label}</option>)}</select><ChevronDown size={13} /></label><Link aria-label={translateText(locale, "Notifications")} className="dashboard-top-icon" href={`/${role}/notifications`}><Bell size={16} /></Link><span className="demo-profile-avatar top-avatar">{roleInitials[role]}</span></div></header><div className="dashboard-content">{activeSection === "Overview" ? <Overview applications={applications} bookings={bookings} displayName={displayName} jobs={marketplaceJobs} locale={locale} role={role} savedIds={savedIds} /> : <SectionContent activeSection={activeSection} applications={applications} bookings={bookings} displayName={displayName} jobs={marketplaceJobs} key={`${role}-${activeSection}`} locale={locale} onApplyJob={onApplyJob} onCreateJob={onCreateJob} onUpdateJob={onUpdateJob} onUpdateApplication={onUpdateApplication} onUpdateBooking={onUpdateBooking} onUpdateJobStatus={onUpdateJobStatus} role={role} savedIds={savedIds} onToggleSave={onToggleSave} onToast={onToast} />}</div></section></main>
}

function Overview({ role, applications, bookings, jobs: marketplaceJobs, locale, savedIds, displayName }: { role: "account" | "worker" | "business" | "admin"; applications: ApplicationRecord[]; bookings: DemoBooking[]; jobs: Job[]; locale: Locale; savedIds: string[]; displayName?: string }) {
  const { notifications } = useDemoNotifications(role, locale)
  const { messages } = useDemoInbox(role)
  const activeBookings = bookings.filter((booking) => !["Completed", "Cancelled"].includes(booking.status))
  const demoWorkerId = workers[0].id
  const customerName = demoUsers.find((user) => user.role === "customer")?.name ?? "Mekdes Alemu"
  const workerApplications = applications.filter((application) => application.workerId === demoWorkerId && application.stage !== "declined")
  const companyName = businessProfiles[0].name
  const companyJobs = marketplaceJobs.filter((job) => job.company === companyName)
  const [verificationStatuses] = useDemoStorageState("carava-demo-verification-statuses", initialVerificationStatuses)
  const [workerProfile] = useDemoStorageState("carava-demo-worker-profile", { headline: workers[0].headline, category: workers[0].category, skills: workers[0].skills.join(", "), rate: String(workers[0].hourlyRate), about: workers[0].about })
  const [workerAvailability] = useDemoStorageState<string[]>("carava-demo-worker-availability", ["Mon", "Tue", "Wed", "Thu", "Fri"])
  const profileFields = [workerProfile.headline, workerProfile.category, workerProfile.skills, workerProfile.rate, workerProfile.about, workerAvailability.length > 0 ? "available" : ""]
  const profileCompletion = `${Math.round(profileFields.filter(Boolean).length / profileFields.length * 100)}%`
  const pendingVerification = dashboardRecords("admin", "Worker verification").filter((row) => /pending/i.test(verificationStatuses[row.ID] ?? row.Status ?? "")).length
  const pendingJobs = marketplaceJobs.filter((job) => job.moderationStatus === "pending").length
  const openDisputes = disputeRecords.filter((record) => record.status !== "resolved").length
  const chartDates = [
    ...bookings.map((booking) => booking.date),
    ...applications.map((application) => application.submittedAt),
    ...workers.map((worker) => worker.joinedAt).filter((date): date is string => Boolean(date)),
    ...demoUsers.map((user) => user.createdAt),
  ]
  const chartCounts = Array.from({ length: 8 }, (_, index) => chartDates.filter((date) => {
    const day = new Date(date).getDay()
    return Number.isNaN(day) ? false : index === 0 || index === 7 ? day === 0 : day === index - 1
  }).length)
  const metrics: [string, string, string, LucideIcon][] = role === "account" ? [["Active bookings", String(activeBookings.length), "Requests in progress", CalendarDays], ["Saved workers", String(savedIds.length), "People you want to work with", Heart], ["Open job posts", String(marketplaceJobs.filter((job) => job.company === customerName).length), "Your demo job posts", BriefcaseBusiness], ["Unread messages", String(notifications.filter((item) => !item.read).length + messages.length), "Updates in this browser", MessageCircle]] : role === "worker" ? [["Profile completion", profileCompletion, "Demo profile is editable", UserRound], ["Active applications", String(workerApplications.length), "Applications still in progress", FileCheck2], ["Upcoming bookings", String(activeBookings.filter((booking) => booking.workerId === demoWorkerId).length), "Requests not yet completed", CalendarDays], ["This month", formatETB(activeBookings.reduce((total, booking) => total + booking.amount, 0), locale), "Demo value of active requests", Wallet]] : role === "business" ? [["Active vacancies", String(companyJobs.filter((job) => job.moderationStatus === "approved").length), "Approved demo vacancies", BriefcaseBusiness], ["Total applicants", String(applications.length), "Demo applications received", Users], ["Shortlisted", String(applications.filter((application) => ["shortlisted", "interview", "selected"].includes(application.stage)).length), "Ready for the next step", BadgeCheck], ["Upcoming interviews", String(applications.filter((application) => application.stage === "interview").length), "Interviews in the demo pipeline", CalendarDays]] : [["Total users", String(new Set([...demoUsers.map((item) => item.id), ...applications.map((item) => item.workerId), ...bookings.map((item) => item.workerId).filter(Boolean)]).size), "Accounts visible in demo data", Users], ["Pending review", String(marketplaceJobs.filter((job) => job.moderationStatus === "pending").length), "Vacancies awaiting moderation", ShieldAlert], ["Active bookings", String(activeBookings.length), "Current demo records", CalendarDays], ["Payment volume", formatETB(bookings.reduce((total, booking) => total + booking.amount, 0), locale), "Demo value of all requests", CircleDollarSign]]
  const localizedMetrics = metrics.map(([label, value, note, Icon]) => [translateText(locale, label), value, translateText(locale, note), Icon] as const)
  const activity: { text: React.ReactNode; time: string; icon: LucideIcon }[] = [
    ...bookings.slice(0, 2).map((booking) => ({ text: <><strong>{booking.id}</strong> · {booking.service}  {translateText(locale, "is")} {booking.status.toLowerCase()}.</>, time: formatDate(booking.date, locale), icon: CalendarDays })),
    ...marketplaceJobs.slice(0, 2).map((job) => ({ text: <><strong>{job.title}</strong> · {job.moderationStatus ?? "approved"}  {translateText(locale, "in the demo job board.")}</>, time: job.posted, icon: BriefcaseBusiness })),
  ].slice(0, 3)
  return <><div className="dashboard-welcome"><div><div className="eyebrow">{new Intl.DateTimeFormat(locale === "am" ? "am-ET" : locale === "om" ? "om-ET" : "en-ET", { weekday: "long", month: "long", day: "numeric", year: "numeric" }).format(new Date()).toUpperCase()} · {translateText(locale, roleNames[role]).toUpperCase()}</div><h1>{translateText(locale, "Good morning")}, {role === "admin" ? "team" : displayName ?? displayNames[role]}.</h1><p>{translateText(locale, role === "admin" ? "Here's what's happening in your Carava demo today." : "Here's what's happening in your Carava space today.")}</p></div>{role !== "admin" && <Link className="button button-primary" href={role === "worker" ? "/worker/my-profile" : role === "business" ? "/business/vacancies" : "/search"}><Plus size={15} />{translateText(locale, role === "worker" ? "Edit profile" : role === "business" ? "Post a vacancy" : "New request")}</Link>}</div><div className="demo-banner"><ShieldCheck size={15} /><span>{translateText(locale, "Demo workspace — the numbers, requests, verifications, and financial activity here are sample data. No real actions are sent to a service.")}</span></div><div className="metric-grid">{localizedMetrics.map(([label, value, note, Icon]) => <article className="metric-card" key={String(label)}><div className="metric-top"><span>{label as string}</span><span className="metric-icon"><Icon size={15} /></span></div><strong>{value as string}</strong><div className="metric-foot">{note as string}</div></article>)}</div><div className="dashboard-columns"><section className="dash-card"><div className="dash-card-header"><h2>{translateText(locale, role === "admin" ? "Platform activity" : "Recent activity")}</h2><Link className="quiet-text-button" href={`/${role}/${role === "account" ? "bookings" : role === "worker" ? "applications" : role === "business" ? "vacancies" : "audit-logs"}`}>{translateText(locale, "View all")}</Link></div><div className="activity-list">{activity.map((item, index) => { const Icon = item.icon; return <div className="activity-row" key={`${item.time}-${index}`}><span className="activity-icon"><Icon size={14} /></span><span className="activity-copy">{item.text}<small>{item.time}</small></span></div> })}</div></section><section className="dash-card"><div className="dash-card-header"><h2>{role === "admin" ? "Review queue" : role === "worker" ? "Suggested opportunities" : "Upcoming"}</h2><Link href={sectionHref(role, role === "admin" ? "Worker verification" : role === "worker" ? "Job discovery" : "Bookings")}>{translateText(locale, "See all")}</Link></div>{role === "admin" ? <div className="activity-list"><div className="booking-row"><span><strong>{translateText(locale, "Worker verification")}</strong><small>{pendingVerification}  {translateText(locale, "profiles waiting")}</small></span><span className="dash-status">{translateText(locale, "Review")}</span></div><div className="booking-row"><span><strong>{translateText(locale, "Job approval")}</strong><small>{pendingJobs}  {translateText(locale, "posts to check")}</small></span><span className="dash-status">{translateText(locale, "Review")}</span></div><div className="booking-row"><span><strong>{translateText(locale, "Open disputes")}</strong><small>{openDisputes}  {translateText(locale, "need attention")}</small></span><span className="dash-status blue">{translateText(locale, "Open")}</span></div></div> : <div className="activity-list">{(role === "worker" ? marketplaceJobs.filter((job) => job.moderationStatus !== "pending" && job.moderationStatus !== "rejected").slice(0, 3) : bookings.slice(0, 3)).map((item) => <div className="booking-row" key={item.id}><span><strong>{"title" in item ? item.title : item.service}</strong><small>{"company" in item ? item.company : `${item.date} · ${item.worker}`}</small></span><span className={`dash-status ${"status" in item && item.status === "Confirmed" ? "green" : ""}`}>{"type" in item ? item.type : item.status}</span></div>)}</div>}</section></div><div className="dashboard-columns"><section className="dash-card"><div className="dash-card-header"><h2>{role === "business" || role === "admin" ? "Activity this month" : "Your momentum"}</h2><span className="metric-foot">{translateText(locale, "Demo snapshot")}</span></div><DemoChart counts={chartCounts} /></section><section className="dash-card"><div className="dash-card-header"><h2>{translateText(locale, "A small reminder")}</h2><ShieldCheck size={17} color="#a87a2c" /></div><p className="dashboard-reminder">{translateText(locale, "Keep your profile clear, your expectations kind, and your conversations on the platform. Good work grows with trust.")}</p><Link className="text-link" href="/help">{translateText(locale, "See our safety tips")} <ArrowRight size={13} /></Link></section></div></>
}

function DemoChart({ counts }: { counts: number[] }) {
  const max = Math.max(1, ...counts)
  return <div aria-label={`Illustrative demo activity chart: ${counts.join(", ")} records by weekday`} className="bar-chart" role="img">{counts.map((count, index) => <div className="bar-chart-column" key={index}><div aria-label={`${count} demo records`} className="bar-chart-bar" style={{ height: `${Math.max(4, (count / max) * 100)}%` }} /><span>{["S", "M", "T", "W", "T", "F", "S", "S"][index]}</span></div>)}</div>
}

type AdminAction = { title: string; text: string; reason: string; action: string; targetId?: string } | null

function SectionContent({ activeSection, role, savedIds, bookings, jobs: marketplaceJobs, applications, locale, displayName, onToggleSave, onUpdateBooking, onApplyJob, onCreateJob, onUpdateJob, onUpdateJobStatus, onUpdateApplication, onToast }: { activeSection: string; role: "account" | "worker" | "business" | "admin"; savedIds: string[]; bookings: DemoBooking[]; jobs: Job[]; applications: ApplicationRecord[]; locale: Locale; displayName?: string; onToggleSave: (id: string) => void; onUpdateBooking: (id: string, status: DemoBooking["status"], update?: Partial<Pick<DemoBooking, "date" | "schedule" | "details" | "completionEvidence">>) => void; onApplyJob: (job: Job) => void; onCreateJob: (title: string, description: string, category?: string, owner?: "business" | "customer") => void; onUpdateJob: (id: string, title: string, description: string, category?: string) => void; onUpdateJobStatus: (id: string, status: NonNullable<Job["moderationStatus"]>) => void; onUpdateApplication: (id: string, stage: ApplicationRecord["stage"]) => void; onToast: (message: string) => void }) {
  const [search, setSearch] = useState("")
  const [statusFilter, setStatusFilter] = useState("")
  const [page, setPage] = useState(1)
  const [confirm, setConfirm] = useState<AdminAction>(null)
  const confirmDialogRef = useDialogFocus(Boolean(confirm), () => setConfirm(null))
  const [viewRecord, setViewRecord] = useState<Record<string, string> | null>(null)
  const viewDialogRef = useDialogFocus(Boolean(viewRecord), () => setViewRecord(null))
  const [reason, setReason] = useState("")
  const isAdmin = role === "admin"
  const workflowHandled = handlesWorkflowSection(role, activeSection)
  const isSharedWorkflowSection = /job|vacanc|application|applicant|candidate|recruit|interview|verification/i.test(activeSection)
  const [auditRows, setAuditRows] = useDemoStorageState("carava-demo-audit-log", demoAuditRecords)
  const [verificationStatuses, setVerificationStatuses] = useDemoStorageState("carava-demo-verification-statuses", initialVerificationStatuses)
  const initialRows = useMemo(() => {
    const sectionRows = dashboardRecords(role, activeSection, marketplaceJobs, applications).map((row) => /verification/i.test(activeSection) && verificationStatuses[row.ID]
      ? { ...row, Status: verificationStatuses[row.ID] }
      : row)
    if (isAdmin && /verification/i.test(activeSection)) sectionRows.sort((a, b) => Number(!/pending/i.test(a.Status ?? "")) - Number(!/pending/i.test(b.Status ?? "")))
    return /audit/i.test(activeSection) ? [...auditRows, ...sectionRows] : sectionRows
  }, [activeSection, applications, auditRows, isAdmin, marketplaceJobs, role, verificationStatuses])
  const [storedRows, setRows] = useDemoStorageState<ReadonlyArray<Record<string, string>>>(`carava-demo-records-${role}-${activeSection}`, initialRows)
  const rows = useMemo(() => {
    if (isSharedWorkflowSection) return initialRows
    const storedById = new Map(storedRows.map((row) => [row.ID, row]))
    return [
      ...initialRows.map((row) => ({ ...row, ...(storedById.get(row.ID) ?? {}) })),
      ...storedRows.filter((row) => !initialRows.some((initial) => initial.ID === row.ID)),
    ]
  }, [initialRows, isSharedWorkflowSection, storedRows])
  const [message, setMessage] = useState("")
  const { messages: inboxMessages } = useDemoInbox(role)
  const { notifications, setNotifications } = useDemoNotifications(role, locale)
  const [preferences, setPreferences] = useDemoStorageState(`carava-demo-preferences-${role}`, { productUpdates: true, profileVisibility: true })
  const productUpdates = preferences.productUpdates
  const profileVisibility = preferences.profileVisibility
  const setProductUpdates = (value: boolean) => setPreferences((current) => ({ ...current, productUpdates: value }))
  const setProfileVisibility = (value: boolean) => setPreferences((current) => ({ ...current, profileVisibility: value }))
  const [createOpen, setCreateOpen] = useState(false)
  const [recordName, setRecordName] = useState("")
  const [recordDetail, setRecordDetail] = useState("")
  const [editingJobId, setEditingJobId] = useState("")
  const [editingRecordId, setEditingRecordId] = useState("")
  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const [fileError, setFileError] = useState("")
  const [profileName, setProfileName] = useDemoStorageState(`carava-demo-profile-${role}`, displayName ?? displayNames[role])
  const [profileHeadline, setProfileHeadline] = useDemoStorageState(`carava-demo-profile-headline-${role}`, role === "business" ? "A welcoming local business" : "A Carava community member")
  const [profileAbout, setProfileAbout] = useDemoStorageState(`carava-demo-profile-about-${role}`, "Tell Adama neighbors a little about your experience, interests, and what you are looking for.")
  const [platformConfig, setPlatformConfig] = useDemoStorageState(`carava-demo-config-${role}-${activeSection}`, { commission: 8, featuredPrice: 250 })
  const [planSettings, setPlanSettings] = useDemoStorageState(`carava-demo-plan-${role}-${activeSection}`, { plan: role === "business" ? "Local Business" : "Free demo", renewal: false })
  const filteredRows = rows.filter((row) => Object.values(row).some((value) => value.toLowerCase().includes(search.toLowerCase())) && (!statusFilter || row.Status === statusFilter))
  const tableColumns = Array.from(new Set(filteredRows.flatMap((row) => Object.keys(row))))
  const pageSize = 6
  const pageCount = Math.max(1, Math.ceil(filteredRows.length / pageSize))
  const pagedRows = filteredRows.slice((page - 1) * pageSize, page * pageSize)
  const statusOptions = Array.from(new Set(rows.map((row) => row.Status).filter(Boolean)))
  const handleAction = (label: string, name: string, targetId?: string) => {
    const targetRow = rows.find((row) => row.ID === targetId) ?? rows.find((row) => (row.Name ?? row.Title ?? row.ID) === name)
    const sensitive = isAdmin && /approve|reject|suspend|activate|refund|delete|resolve|promote|change status|assign|moderate|review|remove/i.test(label)
    if (sensitive) setConfirm({ title: `${label} ${name}?`, text: `This is a demo ${label.toLowerCase()} action. A production system would require server-side authorization and create an audit record.`, reason: "", action: label, targetId: targetRow?.ID })
    else if (label === "View" && targetRow) setViewRecord(targetRow)
    else if (isAdmin && label === "Edit" && targetRow?.ID) {
      if (activeSection === "Job management") setEditingJobId(targetRow.ID)
      else setEditingRecordId(targetRow.ID)
      setRecordName(targetRow.Name ?? targetRow.Title ?? "")
      setRecordDetail(targetRow.Detail ?? targetRow.Description ?? "")
      setCreateOpen(true)
    }
    else if (role === "worker" && label === "Edit" && targetRow?.ID) {
      setEditingRecordId(targetRow.ID)
      setRecordName(targetRow.Name ?? targetRow.Title ?? "")
      setRecordDetail(targetRow.Detail ?? targetRow.Description ?? "")
      setCreateOpen(true)
    }
    else if (role === "business" && activeSection === "Vacancies" && label === "Edit" && targetRow?.ID) {
      const job = marketplaceJobs.find((item) => item.id.toLowerCase() === targetRow.ID?.toLowerCase())
      if (job) { setEditingJobId(job.id); setRecordName(job.title); setRecordDetail(job.description); setCreateOpen(true) }
    }
    else if (role === "business" && /applicant|candidate|recruit|interview/i.test(activeSection)) {
      const stageByAction: Record<string, ApplicationRecord["stage"]> = { Review: "review", Shortlist: "shortlisted", "Schedule interview": "interview", Select: "selected", Decline: "declined" }
      const stage = stageByAction[label]
      if (stage && targetRow?.ID) {
        onUpdateApplication(targetRow.ID, stage)
        onToast(`Demo application moved to ${stage}.`)
      }
    } else if (/mark as read/i.test(label)) {
      setRows((all) => all.map((row) => row.Name === name ? { ...row, Status: "Read" } : row))
      onToast("Demo notification marked as read.")
    } else {
      onToast(`${label} is unavailable for this demo record. No changes were made.`)
    }
  }
  const confirmAction = () => {
    if (!confirm) return
    const actionWord = confirm.title.split(" ")[0]
    const auditRecord = { ID: createDemoId("AU"), Name: confirm.title.replace("?", ""), Admin: displayNames.admin, Date: new Date().toLocaleString(), Status: reason.trim() || "Recorded" }
    setAuditRows((current) => [auditRecord, ...current].slice(0, 100))
    onToast(`Demo audit record added: ${confirm.title.replace("?", "")}${reason.trim() ? ` — ${reason.trim()}` : ""}.`)
    const nextStatus = actionWord === "Approve" ? "Approved" : actionWord === "Reject" ? "Rejected" : actionWord === "Resolve" ? "Resolved" : actionWord === "Suspend" ? "Suspended" : actionWord === "Activate" ? "Active" : actionWord === "Refund" ? "Refunded" : actionWord === "Remove" ? "Removed" : actionWord === "Review" ? "Reviewed" : actionWord === "Moderate" ? "Moderated" : actionWord === "Assign" ? "Assigned" : "Updated"
    const nextRows = rows.map((row) => row.ID === confirm.targetId ? { ...row, Status: nextStatus } : row)
    if (isAdmin && /verification/i.test(activeSection) && confirm.targetId) {
      setVerificationStatuses((current) => ({ ...current, [confirm.targetId!]: actionWord === "Approve" ? "Verified (illustrative)" : "Rejected" }))
    }
    setRows(nextRows)
    if (isAdmin) {
      const audience: DemoRole | DemoRole[] = /verification/i.test(activeSection) ? confirm.targetId === "USR-112" ? "worker" : confirm.targetId === "USR-130" ? "business" : ["worker", "business", "admin"] : /job|vacanc/i.test(activeSection) ? ["worker", "business"] : "admin"
      publishDemoNotification(audience, `Demo ${confirm.action.toLowerCase()} decision recorded for ${confirm.title.replace("?", "")}.`, reason.trim())
    }
    if (["Job approval", "Job management"].includes(activeSection) && confirm.targetId && (confirm.action === "Approve" || confirm.action === "Reject")) onUpdateJobStatus(confirm.targetId, confirm.action === "Approve" ? "approved" : "rejected")
    setConfirm(null); setReason("")
  }
  const createRecord = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const name = recordName.trim()
    if (!name) return
    if ((role === "business" && activeSection === "Vacancies") || (isAdmin && activeSection === "Job management")) {
      if (editingJobId) onUpdateJob(editingJobId, name, recordDetail.trim())
      else onCreateJob(name, recordDetail.trim())
      setRecordName(""); setRecordDetail(""); setEditingJobId(""); setEditingRecordId(""); setCreateOpen(false)
      return
    }
    if ((isAdmin || role === "worker") && editingRecordId) {
      const nextRows = rows.map((row) => row.ID === editingRecordId ? { ...row, ...(Object.hasOwn(row, "Name") ? { Name: name } : {}), ...(Object.hasOwn(row, "Title") ? { Title: name } : {}), ...(Object.hasOwn(row, "Detail") ? { Detail: recordDetail.trim() } : {}) } : row)
      setRows(nextRows)
      setEditingRecordId(""); setRecordName(""); setRecordDetail(""); setCreateOpen(false)
      onToast(translateText(locale, "Demo record updated in this workspace."))
      return
    }
    const requiresDemoFile = role === "worker" && ["Portfolio", "Certificates"].includes(activeSection)
    if (requiresDemoFile && !selectedFile) {
      setFileError("Choose a PDF, JPG, or PNG file for this demo record.")
      return
    }
    const template = rows[0] ?? { ID: "", Name: "", Detail: "", Status: "" }
    const newRecord: Record<string, string> = {}
    Object.keys(template).forEach((key) => {
      newRecord[key] = key === "ID" ? createDemoId("DEMO") : /name|title/i.test(key) ? name : /date|updated|submitted/i.test(key) ? new Date().toISOString().slice(0, 10) : /status/i.test(key) ? (isAdmin ? "Pending review" : "Draft") : key === "Detail" ? recordDetail.trim() || "New demo record" : recordDetail.trim() || "Demo record"
    })
    if (selectedFile) {
      newRecord["File name"] = selectedFile.name
      newRecord["File handling"] = "Filename saved only; no file uploaded"
    }
    const nextRows = [newRecord, ...rows]
    setRows(nextRows)
    setRecordName(""); setRecordDetail(""); setEditingRecordId(""); setSelectedFile(null); setFileError(""); setCreateOpen(false)
    onToast(`“${name}” was added to this demo workspace. The file itself was not uploaded.`)
  }
  const exportRows = () => {
    const csv = [Object.keys(filteredRows[0] ?? {}).join(","), ...filteredRows.map((row) => Object.values(row).map((value) => `"${value.replaceAll('"', '""')}"`).join(","))].join("\n")
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }))
    const link = document.createElement("a"); link.href = url; link.download = `carava-demo-${activeSection.toLowerCase().replaceAll(" ", "-")}.csv`; link.click(); URL.revokeObjectURL(url)
    onToast("Demo report exported as CSV.")
  }
  const canAddNew = (role === "business" && activeSection === "Vacancies") || (role === "worker" && ["Portfolio", "Certificates"].includes(activeSection)) || (isAdmin && /categor|service|job|vacanc|location|promotion|analytics|export/i.test(activeSection))
  const markNotificationRead = (id: string) => setNotifications((current) => current.map((item) => item.id === id && item.audience.includes(role) ? { ...item, read: true } : item))
  const markAllNotificationsRead = () => setNotifications((current) => current.map((item) => item.audience.includes(role) ? { ...item, read: true } : item))
  const sectionDescription = isAdmin ? translateText(locale, "Review and manage illustrative platform records. Sensitive actions below are demo-only and do not change a live service.") : locale === "en" ? `Manage ${activeSection.toLowerCase()} and follow activity here. All actions are local demo interactions.` : translateText(locale, "Manage this workspace section and follow activity here. All actions are local demo interactions.")
  return <><div className="dashboard-welcome"><div><div className="eyebrow">{translateText(locale, roleNames[role])}</div><h1>{translateText(locale, activeSection)}</h1><p>{sectionDescription}</p></div>{canAddNew && <button className="button button-primary" onClick={() => setCreateOpen(true)} type="button"><Plus size={15} />{translateText(locale, "Add new")}</button>}</div>{isAdmin && <div className="demo-banner"><ShieldAlert size={15} /><span>{translateText(locale, "Admin demo only — frontend role selection does not provide real authorization. Every approval and status change is simulated.")}</span></div>}{workflowHandled && <DashboardWorkflow applications={applications} bookings={bookings} locale={locale} marketplaceJobs={marketplaceJobs} onCreateJob={onCreateJob} onUpdateJob={onUpdateJob} onToast={onToast} onUpdateApplication={onUpdateApplication} onUpdateBooking={onUpdateBooking} role={role} section={activeSection} />}{role === "worker" && activeSection === "Verification" && <section className="section-page-card"><h2>{translateText(locale, "Verification status")}</h2><p>{translateText(locale, "Request a sample review to connect your worker profile with the admin demo queue. No identity documents are collected.")}</p><button className="button button-outline button-small" disabled={verificationStatuses["USR-112"] === "Pending review"} onClick={() => { setVerificationStatuses((current) => ({ ...current, "USR-112": "Pending review" })); setRows((current) => current.map((row) => row.ID === "USR-112" ? { ...row, Status: "Pending review" } : row)); onToast("Demo verification request is pending. No documents were uploaded.") }} type="button">{translateText(locale, "Request verification review")}</button></section>}
    {activeSection === "Saved workers" ? <section className="section-page-card"><h2>{translateText(locale, "Your saved professionals")}</h2><p>{translateText(locale, "People you want to keep close. Save or remove profiles anytime.")}</p><WorkerGrid items={workers.filter((worker) => savedIds.includes(worker.id))} savedIds={savedIds} onToggleSave={onToggleSave} locale={locale} />{savedIds.length === 0 && <div className="empty-state"><div className="empty-state-icon"><Heart size={20} /></div><h2>{translateText(locale, "No saved professionals yet")}</h2><p>{translateText(locale, "Browse Adama professionals and tap the heart to keep a profile here.")}</p><Link className="button button-primary button-small" href="/search">{translateText(locale, "Find professionals")} <ArrowRight size={13} /></Link></div>}</section> : null}
    {activeSection === "Job discovery" ? <div className="section-page-card"><h2>{translateText(locale, "Opportunities matched to your skills")}</h2><p>{translateText(locale, "Published demo roles in Adama. Applications are shared with the business and admin workspaces.")}</p><div className="activity-list">{marketplaceJobs.filter((job) => job.moderationStatus !== "pending" && job.moderationStatus !== "rejected").map((job) => { const isApplied = applications.some((application) => application.jobId === job.id && application.workerId === "abebe-tadesse" && application.stage !== "declined"); return <div className="job-card dashboard-job-card" key={job.id}><div className="job-logo">{job.company[0]}</div><div className="job-main"><Link href={`/jobs/${job.id}`}><h3>{job.title}</h3></Link><div className="job-meta"><span>{job.company}</span><span>{job.location}</span><span>{job.salary}</span></div></div><button aria-pressed={isApplied} className="button button-outline button-small" disabled={isApplied} onClick={() => onApplyJob(job)} type="button">{isApplied ? "Applied" : "Apply"}</button></div> })}</div></div> : null}
    {!workflowHandled && role === "account" && activeSection === "My profile" ? <section className="section-page-card profile-editor"><h2>{translateText(locale, "Edit your public profile")}</h2><p>{translateText(locale, "Personal contact details stay private in this frontend demo.")}</p><form className="workflow-form" onSubmit={(event) => { event.preventDefault(); onToast("Demo profile updated in this browser.") }}><label className="field"><span>{translateText(locale, "Display name")}</span><input maxLength={80} minLength={2} onChange={(event) => setProfileName(event.target.value)} required value={profileName} /></label><label className="field"><span>{translateText(locale, "Headline")}</span><input maxLength={100} minLength={3} onChange={(event) => setProfileHeadline(event.target.value)} required value={profileHeadline} /></label><label className="field"><span>{translateText(locale, "About")}</span><textarea maxLength={1200} minLength={20} onChange={(event) => setProfileAbout(event.target.value)} required value={profileAbout} /></label><button className="button button-primary button-small" type="submit">{translateText(locale, "Save profile")}</button></form></section> : null}
    {activeSection === "Messages" ? <section className="section-page-card"><h2>{translateText(locale, "Inbox")}</h2><p>{translateText(locale, "Demo messages stay in this browser. Nothing is delivered to another person.")}</p><div className="message-thread">{inboxMessages.map((item) => <div className={`message-bubble ${item.authorRole === role ? "outgoing" : ""}`} key={item.id}><strong>{item.authorRole === role ? "You" : item.author}</strong><p>{item.body}</p><small>{item.subject}  {translateText(locale, "· Demo")}</small></div>)}</div><form className="message-compose" onSubmit={(event) => { event.preventDefault(); if (!message.trim()) return; sendDemoInboxMessage([role], "You", message, role, "Workspace conversation"); setMessage(""); onToast(translateText(locale, "Demo message saved in this browser.")) }}><label className="sr-only" htmlFor="demo-message">{translateText(locale, "Write a demo message")}</label><input id="demo-message" onChange={(event) => setMessage(event.target.value)} placeholder={translateText(locale, "Write a demo message")} value={message} /><button aria-label={translateText(locale, "Send demo message")} className="button button-primary" type="submit">{translateText(locale, "Send")} <ArrowRight size={14} /></button></form></section> : null}
    {activeSection === "Notifications" ? <section className="section-page-card"><div className="dash-card-header"><div><h2>{translateText(locale, "Your updates")}</h2><p className="notification-description">{translateText(locale, "Stay in the loop about your activity on Carava.")}</p></div><button className="table-action" disabled={notifications.every((item) => item.read)} onClick={() => { markAllNotificationsRead(); onToast(translateText(locale, "All demo notifications marked as read.")) }} type="button">{translateText(locale, "Mark all read")}</button></div>{notifications.length === 0 && <div className="empty-state"><div className="empty-state-icon"><Bell size={20} /></div><h2>{translateText(locale, "No notifications")}</h2><p>{translateText(locale, "New demo activity will appear here.")}</p></div>}{notifications.map((item) => <div className={`notification-row ${item.read ? "" : "unread"}`} key={item.id}><p>{item.displayTitle}<small>{item.time} · {item.detail ?? translateText(locale, "Demo notification")}</small></p><button aria-pressed={Boolean(item.read)} className="table-action" disabled={item.read} onClick={() => { markNotificationRead(item.id); onToast(translateText(locale, "Demo notification marked as read.")) }} type="button">{item.read ? translateText(locale, "Read") : translateText(locale, "Mark read")}</button></div>)}</section> : null}
    {activeSection === "Settings" || activeSection === "Privacy & data" ? <section className="section-page-card"><h2>{activeSection}</h2><p>{translateText(locale, "Choose how this demo workspace behaves. Preferences are illustrative and do not update a production account.")}</p><div className="settings-row"><span><strong>{translateText(locale, "Product updates")}</strong><small>{translateText(locale, "Helpful news about workers and opportunities")}</small></span><button aria-checked={productUpdates} aria-label={translateText(locale, "Toggle product updates")} className={`switch ${productUpdates ? "on" : ""}`} onClick={() => setProductUpdates(!productUpdates)} role="switch" type="button"><span /></button></div><div className="settings-row"><span><strong>{translateText(locale, "Profile visibility")}</strong><small>{translateText(locale, "Let people discover your public profile")}</small></span><button aria-checked={profileVisibility} aria-label={translateText(locale, "Toggle profile visibility")} className={`switch ${profileVisibility ? "on" : ""}`} onClick={() => setProfileVisibility(!profileVisibility)} role="switch" type="button"><span /></button></div><div className="settings-row"><span><strong>{translateText(locale, "Language")}</strong><small>{translateText(locale, "Current language:")} {localeLabelsFor(locale)}</small></span><span className="dash-status blue">{localeLabelsFor(locale)}</span></div><button className="button button-primary button-small" onClick={() => onToast(translateText(locale, "Your demo preferences have been saved in this browser."))} type="button">{translateText(locale, "Save preferences")}</button></section> : null}
    {isAdmin && (activeSection === "Reviews" || activeSection === "Reviews & moderation") ? <section className="section-page-card"><h2>{translateText(locale, "Reviews and feedback")}</h2><p>{translateText(locale, "Reviews help good work travel through a community.")}</p><DataTable columns={Object.keys(rows[0] ?? {})} locale={locale} onAction={handleAction} role={role} rows={filteredRows} section={activeSection} /></section> : null}
    {(activeSection === "Commission configuration" || activeSection === "Platform settings") ? <section className="section-page-card"><h2>{translateText(locale, activeSection)} {translateText(locale, "configuration")}</h2><p>{translateText(locale, "Demo settings are editable and remain illustrative; production pricing requires backend controls and audited permissions.")}</p><form className="workflow-form" onSubmit={(event) => { event.preventDefault(); onToast(translateText(locale, "Demo configuration saved. Nothing has changed in production.")) }}><div className="settings-row"><span><strong>{translateText(locale, "Marketplace commission")}</strong><small>{translateText(locale, "Example percentage for completed services")}</small></span><label className="number-control"><input aria-label={translateText(locale, "Commission percentage")} max="30" min="0" onChange={(event) => setPlatformConfig((current) => ({ ...current, commission: Math.min(30, Math.max(0, Number(event.target.value) || 0)) }))} required type="number" value={platformConfig.commission} /><span>%</span></label></div><div className="settings-row"><span><strong>{translateText(locale, "Featured listing price")}</strong><small>{translateText(locale, "Sample price per job promotion")}</small></span><label className="number-control"><input aria-label={translateText(locale, "Featured listing price in ETB")} max="100000" min="0" onChange={(event) => setPlatformConfig((current) => ({ ...current, featuredPrice: Math.min(100000, Math.max(0, Number(event.target.value) || 0)) }))} required type="number" value={platformConfig.featuredPrice} /><span>ETB</span></label></div><button className="button button-primary button-small" type="submit">{translateText(locale, "Save configuration")}</button></form><p className="demo-data-note">{translateText(locale, "Saved to this browser demo only. No live pricing or platform settings changed.")}</p></section> : null}
    {(activeSection === "Subscription" || activeSection === "Premium subscription") ? <section className="section-page-card"><h2>{translateText(locale, activeSection)} {translateText(locale, "options")}</h2><p>{translateText(locale, "Choose an illustrative plan. This demo does not bill or activate a real subscription.")}</p><label className="field"><span>{translateText(locale, "Plan")}</span><select aria-label={translateText(locale, "Plan")} onChange={(event) => setPlanSettings((current) => ({ ...current, plan: event.target.value }))} value={planSettings.plan}><option>{translateText(locale, "Free demo")}</option><option>{translateText(locale, "Worker Plus")}</option><option>{translateText(locale, "Local Business")}</option></select></label><div className="settings-row"><span><strong>{translateText(locale, "Renewal reminder")}</strong><small>{translateText(locale, "Show a reminder in this demo before the sample plan renews")}</small></span><button aria-checked={planSettings.renewal} aria-label={translateText(locale, "Toggle renewal reminder")} className={`switch ${planSettings.renewal ? "on" : ""}`} onClick={() => setPlanSettings((current) => ({ ...current, renewal: !current.renewal }))} role="switch" type="button"><span /></button></div><button className="button button-primary button-small" onClick={() => onToast(translateText(locale, "Demo plan preferences saved. No charge was made."))} type="button">{translateText(locale, "Save configuration")}</button></section> : null}
    {workflowHandled || activeSection === "Availability calendar" || activeSection === "My job posts" || activeSection === "Applications" || activeSection === "Messages" || activeSection === "Notifications" || activeSection === "Settings" || activeSection === "Privacy & data" || activeSection === "Earnings" || activeSection === "Payments" || activeSection === "Payouts" || activeSection === "Transactions" || activeSection === "Receipts" || activeSection === "Reviews" || activeSection === "Reviews & moderation" || activeSection === "Commission configuration" || activeSection === "Platform settings" || activeSection === "Subscription" || activeSection === "Premium subscription" || activeSection === "Job discovery" || activeSection === "Saved workers" || activeSection === "Bookings" || activeSection === "Service requests" || activeSection === "Assignments" || activeSection === "My profile" || activeSection === "Company profile" || activeSection === "Profile" ? null : <section className="section-page-card"><h2>{translateText(locale, activeSection)}</h2><p>{translateText(locale, getSectionHelp(role, activeSection))}</p><div className="section-toolbar"><label className="dashboard-search-wrap"><Search size={15} /><span className="sr-only">{`${t(locale, "search")} ${translateText(locale, activeSection)}`}</span><input className="dashboard-search" onChange={(event) => { setSearch(event.target.value); setPage(1) }} placeholder={`${t(locale, "search")} ${translateText(locale, activeSection).toLowerCase()}`} value={search} /></label><div className="section-toolbar-actions"><label className="field status-filter"><span className="sr-only">{translateText(locale, "Filter by status")}</span><select aria-label={translateText(locale, "Filter by status")} onChange={(event) => { setStatusFilter(event.target.value); setPage(1) }} value={statusFilter}><option value="">{translateText(locale, "All statuses")}</option>{statusOptions.map((status) => <option key={status} value={status}>{translateText(locale, status)}</option>)}</select></label>{(activeSection === "Exports" || activeSection === "Analytics & reports" || activeSection === "Audit logs") && <button className="table-action" onClick={exportRows} type="button"><ArrowDownToLine size={13} />  {translateText(locale, "Export CSV")}</button>}{(!isAdmin || /categor|service|job|vacanc|location|promotion/i.test(activeSection)) && <button className="table-action" onClick={() => { setEditingRecordId(""); setEditingJobId(""); setRecordName(""); setRecordDetail(""); setCreateOpen(!createOpen) }} type="button"><Plus size={13} /> {translateText(locale, "Add new")}</button>}</div></div>{createOpen && <form className="new-record-form" onSubmit={createRecord}><h3>{editingJobId ? "Edit vacancy draft" : editingRecordId ? "Edit demo record" : "Create demo record"}</h3><label className="field"><span>{translateText(locale, "Name or title")}</span><input autoFocus maxLength={100} minLength={2} onChange={(event) => setRecordName(event.target.value)} required value={recordName} /></label><label className="field"><span>{translateText(locale, "Details")}</span><input maxLength={160} onChange={(event) => setRecordDetail(event.target.value)} value={recordDetail} /></label>{role === "worker" && ["Portfolio", "Certificates"].includes(activeSection) && <><label className="field"><span>{translateText(locale, "Upload demo file (PDF, JPG, or PNG; up to 10 MB)")}</span><input accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" aria-describedby="demo-file-note" onChange={(event) => { const file = event.currentTarget.files?.[0] ?? null; const allowedType = !file?.type || ["application/pdf", "image/jpeg", "image/png"].includes(file.type); const allowedName = Boolean(file && /\.(pdf|jpe?g|png)$/i.test(file.name)); if (file && (file.size > 10 * 1024 * 1024 || !allowedName || !allowedType)) { setSelectedFile(null); setFileError(file.size > 10 * 1024 * 1024 ? "Choose a file smaller than 10 MB." : "Choose a PDF, JPG, or PNG file."); event.currentTarget.value = ""; return } setSelectedFile(file); setFileError("") }} required type="file" /></label><p className="demo-data-note" id="demo-file-note">{translateText(locale, "The demo keeps the file name only in this browser. It does not upload or retain the file contents.")}</p>{fileError && <p className="form-error" role="alert">{fileError}</p>}</>}<div><button className="button button-outline button-small" onClick={() => { setCreateOpen(false); setEditingJobId(""); setEditingRecordId(""); setRecordName(""); setRecordDetail(""); setSelectedFile(null); setFileError("") }} type="button">{translateText(locale, "Cancel")}</button><button className="button button-primary button-small" type="submit">{editingJobId ? "Save vacancy draft" : editingRecordId ? "Save demo record" : "Create demo record"}</button></div></form>}<DataTable columns={tableColumns} locale={locale} onAction={handleAction} role={role} section={activeSection} rows={pagedRows} /><div className="table-pagination"><span>{translateText(locale, "Showing")} {filteredRows.length ? (page - 1) * pageSize + 1 : 0}–{Math.min(page * pageSize, filteredRows.length)} {translateText(locale, "of")} {filteredRows.length} {translateText(locale, "records")}</span><div><button aria-label={translateText(locale, "Previous page")} className="table-action" disabled={page <= 1} onClick={() => setPage((current) => Math.max(1, current - 1))} type="button">{translateText(locale, "Previous")}</button><span aria-live="polite">{translateText(locale, "Page")} {page} {translateText(locale, "of")} {pageCount}</span><button aria-label={translateText(locale, "Next page")} className="table-action" disabled={page >= pageCount} onClick={() => setPage((current) => Math.min(pageCount, current + 1))} type="button">{translateText(locale, "Next")}</button></div></div></section>}
    {viewRecord && <div className="confirm-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) setViewRecord(null) }}><section aria-labelledby="record-view-title" aria-modal="true" className="confirm-dialog" ref={viewDialogRef} role="dialog" tabIndex={-1}><h2 id="record-view-title">{translateText(locale, viewRecord.Name ?? viewRecord.Title ?? "Record details")}</h2><dl className="admin-record-fields">{Object.entries(viewRecord).map(([key, value]) => <div key={key}><dt>{translateText(locale, key)}</dt><dd>{translateText(locale, value)}</dd></div>)}</dl><div className="confirm-dialog-actions"><button className="button button-primary button-small" onClick={() => setViewRecord(null)} type="button">{translateText(locale, "Close details")}</button></div></section></div>}
    {confirm && <div className="confirm-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) setConfirm(null) }}><section aria-labelledby="confirm-title" aria-modal="true" className="confirm-dialog" ref={confirmDialogRef} role="dialog" tabIndex={-1}><h2 id="confirm-title">{confirm.title}</h2><p>{confirm.text}</p><label className="field reason-field"><span>{translateText(locale, "Reason for this demo action")}</span><textarea aria-required="true" onChange={(event) => setReason(event.target.value)} placeholder={translateText(locale, "Required audit note")} required value={reason} /></label><div className="confirm-dialog-actions"><button className="button button-outline button-small" onClick={() => setConfirm(null)} type="button">{translateText(locale, "Cancel")}</button><button className="button button-primary button-small" disabled={!reason.trim()} onClick={confirmAction} type="button">{translateText(locale, "Confirm demo action")}</button></div></section></div>}
  </>
}

function localeLabelsFor(locale: Locale) { return localeLabels[locale] }

function availableTableActions(role: string, section: string, status: string) {
  const value = status.toLowerCase()
  if (role === "business" && section === "Vacancies") return ["Edit"]
  if (role === "worker" && /certificate/i.test(section)) return ["View"]
  if (role === "business" && /applicant|candidate|recruit|interview/i.test(section)) {
    if (value.includes("submitted") || value.includes("review")) return ["Review", "Shortlist", "Decline"]
    if (value.includes("shortlisted")) return ["Schedule interview", "Decline"]
    if (value.includes("interview")) return ["Select", "Decline"]
    return ["View"]
  }
  if (role === "worker") return ["View", "Edit"]
  return ["View"]
}

function DataTable({ columns, rows, onAction, role, section, locale }: { columns: string[]; rows: ReadonlyArray<Record<string, string>>; onAction: (label: string, name: string, targetId?: string) => void; role: string; section: string; locale: Locale }) {
  if (role === "admin") return <AdminRecordsWorkspace columns={columns} locale={locale} rows={rows} section={section} onAction={onAction} />
  const statusColumn = columns.find((column) => column.toLowerCase() === "status")
  return <div className="table-scroll"><table className="simple-table"><thead><tr>{columns.map((column) => <th key={column}>{translateText(locale, column)}</th>)}<th>{translateText(locale, "Action")}</th></tr></thead><tbody>{rows.map((row, index) => { const name = row.Name ?? row.Title ?? row.ID ?? `Record ${index + 1}`; const currentStatus = statusColumn ? row[statusColumn] : ""; const actions = availableTableActions(role, section, currentStatus); return <tr key={`${name}-${index}`}>{columns.map((column) => <td data-label={translateText(locale, column)} key={column}>{column.toLowerCase() === "status" ? <span className={`dash-status ${/approved|verified|active|completed|read|resolved/i.test(row[column]) ? "green" : /rejected|suspended/i.test(row[column]) ? "red" : ""}`}>{translateText(locale, row[column])}</span> : column.toLowerCase() === "name" || column.toLowerCase() === "title" ? <strong>{row[column]}</strong> : row[column]}</td>)}<td data-label={translateText(locale, "Action")}><div className="table-actions">{actions.map((action) => <button className={`table-action ${action === "Approve" ? "approve" : ""}`} key={action} onClick={() => onAction(action, name, row.ID)} type="button">{translateText(locale, action)}</button>)}</div></td></tr> })}{rows.length === 0 && <tr><td className="no-results-cell" colSpan={columns.length + 1}>{translateText(locale, "No demo records match your search.")}</td></tr>}</tbody></table></div>
}

function AdminRecordsWorkspace({ section, columns, rows, onAction, locale }: { section: string; columns: string[]; rows: ReadonlyArray<Record<string, string>>; onAction: (label: string, name: string, targetId?: string) => void; locale: Locale }) {
  const actionsFor = (status: string) => {
    const value = status.toLowerCase()
    if (/analytics|exports?/.test(section.toLowerCase())) return ["View"]
    if (/category|subcategory|service|location|advertisement|promotion|subscription|role.*permission/.test(section.toLowerCase())) return value.includes("pending") ? ["Review", "Approve", "Reject"] : ["View", "Edit", "Remove"]
    if (/verif|job approval/.test(section.toLowerCase())) return value.includes("pending") ? ["Approve", "Reject"] : ["View", "Edit"]
    if (/payout/.test(section.toLowerCase())) return value.includes("pending") ? ["Review", "Approve payout", "Reject"] : ["View"]
    if (/refund|payment|transaction/.test(section.toLowerCase())) return value.includes("pending") ? ["Review", "Refund", "Reject"] : value.includes("completed") ? ["View", "Refund"] : ["View"]
    if (/review/.test(section.toLowerCase())) return value.includes("flagged") ? ["Approve", "Remove"] : ["View", "Remove"]
    if (/support|emergency/.test(section.toLowerCase())) return value.includes("pending") || value.includes("open") ? ["Review", "Resolve"] : ["View"]
    if (/user|customer|worker|business|team member/.test(section.toLowerCase())) return value.includes("pending") ? ["Review", "Approve", "Reject"] : value.includes("suspended") ? ["Activate"] : ["View", "Suspend"]
    if (/job management|vacanc/.test(section.toLowerCase())) return value.includes("pending") ? ["Approve", "Reject"] : ["View", "Edit"]
    if (value.includes("pending")) return ["Review", "Approve", "Reject"]
    return ["View", "Edit"]
  }
  const description = /verif/i.test(section) ? "Review submitted identity or organization states. All example decisions require a reason and remain simulated." : /job approval/i.test(section) ? "Moderate vacancy submissions before they appear in the public demo job board." : /payment|transaction|payout|refund/i.test(section) ? "Inspect illustrative financial records. No money moves and each action requires a reason." : /review/i.test(section) ? "Review user-submitted feedback and moderation flags. No public review is changed." : /support|emergency/i.test(section) ? "Triage sample support requests. Replies and resolutions are not sent to real users." : `Manage ${section.toLowerCase()} records in this demo operations workspace.`
  return <div className="admin-records-workspace"><div className="admin-queue-note"><ShieldAlert size={16} /><span>{description}</span></div>{rows.length ? <div className="admin-record-grid">{rows.map((row, index) => { const name = row.Name ?? row.Title ?? row.ID ?? `Record ${index + 1}`; const status = row.Status ?? "Unspecified"; const fields = columns.filter((column) => !["id", "name", "title", "status"].includes(column.toLowerCase()) && row[column]); return <article className="admin-record-card" key={`${row.ID ?? name}-${index}`}><div className="admin-record-header"><div><span className="eyebrow">{row.ID ?? section}</span><h3>{name}</h3></div><span className={`dash-status ${/approved|verified|active|completed|resolved|published/i.test(status) ? "green" : /rejected|suspended|removed/i.test(status) ? "red" : "blue"}`}>{translateText(locale, status)}</span></div>{fields.length > 0 && <dl className="admin-record-fields">{fields.map((field) => <div key={field}><dt>{translateText(locale, field)}</dt><dd>{row[field]}</dd></div>)}</dl>}<div className="table-actions">{actionsFor(status).map((action) => <button className={`table-action ${/approve/i.test(action) ? "approve" : ""} ${/reject|refund|remove|suspend/i.test(action) ? "danger-action" : ""}`} key={action} onClick={() => onAction(action, name, row.ID)} type="button">{translateText(locale, action)}</button>)}</div></article>})}</div> : <div className="empty-state"><h3>{translateText(locale, "No matching records")}</h3><p>{translateText(locale, "There are no demo records for this filter.")}</p></div>}</div>
}

function getSectionHelp(role: string, section: string) {
  if (role === "admin") return `${section} review and sample records. Confirmations create visible demo audit feedback; no production records are changed.`
  if (/verification/i.test(section)) return "Follow illustrative verification progress. Documents and approvals are not uploaded or reviewed by a live team."
  if (/profile/i.test(section)) return "Keep your information current so people know who they are working with. Personal contact details stay private in public profiles."
  if (/availability/i.test(section)) return "Manage the days you are open to new conversations. Availability here is a frontend-only demonstration."
  if (/message/i.test(section)) return "Continue conversations in your Carava workspace. Messages in this prototype are never delivered to another person."
  if (role === "worker" && ["Portfolio", "Certificates"].includes(section)) return "Portfolio and certificate records keep file names only in this browser. No file contents are uploaded."
  return `Review your ${section.toLowerCase()} activity. This page uses consistent demo records and does not connect to live services.`
}